import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] g = new long[(int) n][(int) m];
        for (int i = 0; i < g.length; i++) {
            for (int j = 0; j < g[i].length; j++) {
                g[i][j] = Long.parseLong(next());
            }
        }

        Map<String, Integer> count = new HashMap<>();
        int best = 0;
        for (int i = 0; i < n; i++) {
            StringBuilder key = new StringBuilder();
            for (int j = 0; j < m; j++) key.append(g[i][j] ^ g[i][0]);
            best = Math.max(best, count.merge(key.toString(), 1, Integer::sum));
        }
        System.out.println(best);
    }
}
